'use strict';

// ==================== uniqueBy ====================
// Set 使用 SameValueZero 比较键：1 与 "1" 视为不同，且不受 Object.prototype 影响
function uniqueBy(items, keyOf) {
  const seen = new Set();
  const result = [];
  for (const item of items) {
    const key = keyOf(item);
    if (seen.has(key)) continue;
    seen.add(key);
    result.push(item);
  }
  return result;
}

module.exports = { uniqueBy };

'use strict';

const { test } = require('node:test');
const assert = require('node:assert/strict');
const { uniqueBy } = require('../src/solution.cjs');

const byId = (item) => item.id;

test('keeps the first item for each duplicate key, in input order', () => {
  const items = [
    { id: 2, name: 'b1' },
    { id: 1, name: 'a1' },
    { id: 2, name: 'b2' },
    { id: 3, name: 'c1' },
    { id: 1, name: 'a2' },
  ];

  assert.deepEqual(uniqueBy(items, byId), [
    { id: 2, name: 'b1' },
    { id: 1, name: 'a1' },
    { id: 3, name: 'c1' },
  ]);
});

test('treats number 1 and string "1" as different keys', () => {
  const items = [
    { k: 1, v: 'num-a' },
    { k: '1', v: 'str-a' },
    { k: 1, v: 'num-b' },
    { k: '1', v: 'str-b' },
  ];

  assert.deepEqual(uniqueBy(items, (x) => x.k), [
    { k: 1, v: 'num-a' },
    { k: '1', v: 'str-a' },
  ]);
});

test('returns [] for empty input', () => {
  assert.deepEqual(uniqueBy([], byId), []);
});

test('returns a new array and does not mutate the input', () => {
  const items = [{ id: 1 }, { id: 1 }, { id: 2 }];
  const snapshot = structuredClone(items);

  const result = uniqueBy(items, byId);

  assert.notEqual(result, items);
  assert.deepEqual(items, snapshot);
  assert.equal(items.length, 3);
});

test('treats "__proto__" and other Object.prototype names as ordinary keys', () => {
  const items = [
    { k: '__proto__', v: 1 },
    { k: 'constructor', v: 2 },
    { k: '__proto__', v: 3 },
    { k: 'toString', v: 4 },
    { k: 'constructor', v: 5 },
  ];

  assert.deepEqual(uniqueBy(items, (x) => x.k), [
    { k: '__proto__', v: 1 },
    { k: 'constructor', v: 2 },
    { k: 'toString', v: 4 },
  ]);
});

test('returns all items when every key is distinct', () => {
  const items = [1, 2, 3];
  assert.deepEqual(uniqueBy(items, (x) => x), [1, 2, 3]);
});

test('returns a single item when all keys are the same', () => {
  assert.deepEqual(uniqueBy(['a', 'b', 'c'], () => 'same'), ['a']);
});

