'use strict';

const { test } = require('node:test');
const assert = require('node:assert/strict');
const { uniqueBy } = require('../src/solution.cjs');

const byId = (item) => item.id;

test('keeps the first item for each duplicate key, in input order', () => {
  const items = [
    { id: 'b', n: 1 },
    { id: 'a', n: 2 },
    { id: 'b', n: 3 },
    { id: 'c', n: 4 },
    { id: 'a', n: 5 },
  ];
  assert.deepEqual(uniqueBy(items, byId), [
    { id: 'b', n: 1 },
    { id: 'a', n: 2 },
    { id: 'c', n: 4 },
  ]);
});

test('returns a new array even when there are no duplicates', () => {
  const items = [1, 2, 3];
  const result = uniqueBy(items, (x) => x);
  assert.deepEqual(result, [1, 2, 3]);
  assert.notEqual(result, items);
});

test('distinguishes number 1 from string "1"', () => {
  assert.deepEqual(uniqueBy([1, '1', 1, '1'], (x) => x), [1, '1']);
});

test('treats mixed key types as distinct keys', () => {
  const items = [
    { k: 1, v: 'num' },
    { k: '1', v: 'str' },
    { k: 0, v: 'zero' },
    { k: '0', v: 'str zero' },
    { k: 1, v: 'num again' },
  ];
  assert.deepEqual(uniqueBy(items, (x) => x.k), [
    { k: 1, v: 'num' },
    { k: '1', v: 'str' },
    { k: 0, v: 'zero' },
    { k: '0', v: 'str zero' },
  ]);
});

test('returns [] for empty input', () => {
  assert.deepEqual(uniqueBy([], byId), []);
});

test('does not mutate the input array or its items', () => {
  const items = Object.freeze([
    Object.freeze({ id: 'x' }),
    Object.freeze({ id: 'x' }),
    Object.freeze({ id: 'y' }),
  ]);
  const snapshot = JSON.stringify(items);
  const result = uniqueBy(items, byId);
  assert.equal(JSON.stringify(items), snapshot);
  assert.equal(items.length, 3);
  assert.equal(result.length, 2);
  assert.equal(result[0], items[0]);
});

test('treats "__proto__" and other Object.prototype names as ordinary keys', () => {
  const keys = ['__proto__', 'constructor', '__proto__', 'toString', 'constructor'];
  assert.deepEqual(uniqueBy(keys, (k) => k), ['__proto__', 'constructor', 'toString']);
});

test('calls keyOf once per item, in input order', () => {
  const calls = [];
  uniqueBy(['a', 'b', 'a'], (item) => {
    calls.push(item);
    return item;
  });
  assert.deepEqual(calls, ['a', 'b', 'a']);
});

