test('mixed key types: number key 1 and string key "1" yield separate entries', () => {
  const items = [
    { k: 1, v: 'num-a' },
    { k: '1', v: 'str-a' },
    { k: 1, v: 'num-b' },
    { k: '1', v: 'str-b' },
  ];
  assert.deepEqual(uniqueBy(items, (x) => x.k), [
    { k: 1, v: 'num-a' },
    { k: '1', v: 'str-a' },
  ]);
});

test('returns [] for empty input', () => {
  assert.deepEqual(uniqueBy([], (x) => x), []);
});

test('does not mutate the input array or its items', () => {
  const items = [{ id: 1 }, { id: 1 }, { id: 2 }];
  const snapshot = JSON.stringify(items);
  const original = items.slice();
  const result = uniqueBy(items, (x) => x.id);
  assert.equal(JSON.stringify(items), snapshot);
  assert.deepEqual(items, original);
  assert.notEqual(result, items);
  assert.equal(result[0], items[0]);
});

test('"__proto__" and other Object.prototype names are ordinary keys', () => {
  const items = ['__proto__', 'constructor', '__proto__', 'toString', 'constructor', 'hasOwnProperty'];
  assert.deepEqual(uniqueBy(items, (x) => x), ['__proto__', 'constructor', 'toString', 'hasOwnProperty']);
});

