def reference_merge(intervals):
    # 暴力参照：反复合并任意两个相交（含端点相接）的区间直到不变
    items = [list(p) for p in intervals]
    changed = True
    while changed:
        changed = False
        for i in range(len(items)):
            for j in range(i + 1, len(items)):
                a, b = items[i], items[j]
                if a[0] <= b[1] and b[0] <= a[1]:
                    items[i] = [min(a[0], b[0]), max(a[1], b[1])]
                    del items[j]
                    changed = True
                    break
            if changed:
                break
    return sorted(items)


class MergeIntervalsTest(unittest.TestCase):
    def test_empty_input(self):
        self.assertEqual(merge_intervals([]), [])

    def test_single_interval(self):
        self.assertEqual(merge_intervals([[2, 7]]), [[2, 7]])

    def test_single_point_interval(self):
        self.assertEqual(merge_intervals([[4, 4]]), [[4, 4]])

    def test_touching_endpoints_merge(self):
        self.assertEqual(merge_intervals([[1, 3], [3, 5]]), [[1, 5]])

    def test_gap_of_one_does_not_merge(self):
        self.assertEqual(merge_intervals([[1, 3], [4, 5]]), [[1, 3], [4, 5]])

    def test_overlapping_intervals(self):
        self.assertEqual(merge_intervals([[1, 4], [2, 6], [8, 9]]), [[1, 6], [8, 9]])

    def test_unsorted_input(self):
        self.assertEqual(
            merge_intervals([[8, 10], [1, 3], [2, 6], [15, 18]]),
            [[1, 6], [8, 10], [15, 18]],
        )

    def test_containment(self):
        self.assertEqual(merge_intervals([[1, 10], [2, 3], [4, 5]]), [[1, 10]])

    def test_containment_listed_after_container(self):
        self.assertEqual(merge_intervals([[2, 3], [1, 10]]), [[1, 10]])

    def test_duplicates(self):
        self.assertEqual(merge_intervals([[1, 2], [1, 2], [1, 2]]), [[1, 2]])

    def test_identical_start_different_end(self):
        self.assertEqual(merge_intervals([[1, 2], [1, 5], [1, 3]]), [[1, 5]])

    def test_negative_coordinates(self):
        self.assertEqual(
            merge_intervals([[-5, -2], [-3, 0], [2, 4]]),
            [[-5, 0], [2, 4]],
        )

    def test_negative_touching(self):
        self.assertEqual(merge_intervals([[-4, -2], [-2, -1]]), [[-4, -1]])

    def test_all_merge_into_one(self):
        self.assertEqual(merge_intervals([[5, 6], [1, 2], [2, 5]]), [[1, 6]])

    def test_input_not_mutated(self):
        intervals = [[8, 10], [1, 3], [2, 6]]
        snapshot = [list(p) for p in intervals]
        merge_intervals(intervals)
        self.assertEqual(intervals, snapshot)
        self.assertIsInstance(intervals, list)
        for pair, original in zip(intervals, snapshot):
            self.assertEqual(pair, original)

    def test_output_does_not_alias_input_pairs(self):
        intervals = [[1, 3], [5, 7]]
        result = merge_intervals(intervals)
        self.assertIsNot(result[0], intervals[0])
        result[0][1] = 999
        self.assertEqual(intervals, [[1, 3], [5, 7]])

    def test_output_is_sorted_and_nonoverlapping(self):
        result = merge_intervals([[9, 12], [-1, 0], [3, 4], [0, 2], [11, 20]])
        for a, b in zip(result, result[1:]):
            self.assertLess(a[1], b[0])
        self.assertEqual(result, sorted(result))

    def test_matches_reference_on_random_inputs(self):
        rng = random.Random(20261028)
        for _ in range(500):
            n = rng.randint(0, 12)
            intervals = []
            for _ in range(n):
                s = rng.randint(-20, 20)
                e = s + rng.randint(0, 8)
                intervals.append([s, e])
            with self.subTest(intervals=intervals):
                self.assertEqual(
                    merge_intervals(intervals), reference_merge(intervals)
                )


