function deferred() {
  let resolve;
  let reject;
  const promise = new Promise((res, rej) => {
    resolve = res;
    reject = rej;
  });
  return { promise, resolve, reject };
}

// Drains the microtask queue so pending continuations run before assertions.
function flush() {
  return new Promise((resolve) => setImmediate(resolve));
}

function controlledFn() {
  const calls = [];
  const fn = (item, index) => {
    const d = deferred();
    calls.push({ item, index, ...d });
    return d.promise;
  };
  return { fn, calls };
}

test('never has more than limit calls in flight and refills as calls settle', async () => {
  const { fn, calls } = controlledFn();
  const p = mapLimit([0, 1, 2, 3, 4], 2, fn);

  await flush();
  assert.equal(calls.length, 2);

  calls[0].resolve('a');
  await flush();
  assert.equal(calls.length, 3);

  calls[1].resolve('b');
  await flush();
  assert.equal(calls.length, 4);

  calls[2].resolve('c');
  calls[3].resolve('d');
  await flush();
  assert.equal(calls.length, 5);

  calls[4].resolve('e');
  assert.deepEqual(await p, ['a', 'b', 'c', 'd', 'e']);
});

