const assert = require('node:assert/strict');
const { retry } = require('../src/solution.cjs');

function fakeSleep() {
  const calls = [];
  const sleep = async (ms) => {
    calls.push(ms);
  };
  return { sleep, calls };
}

function failingTimes(count, error = new Error('boom')) {
  let calls = 0;
  const operation = async () => {
    calls += 1;
    if (calls <= count) {
      throw error;
    }
    return `ok after ${calls}`;
  };
  return { operation, callCount: () => calls };
}

test('returns the first value without sleeping when the operation succeeds', async () => {
  const { sleep, calls } = fakeSleep();
  let invocations = 0;
  const value = await retry(async () => {
    invocations += 1;
    return 'done';
  }, { attempts: 3, delayMs: 50, sleep, shouldRetry: () => true });

  assert.equal(value, 'done');
  assert.equal(invocations, 1);
  assert.deepEqual(calls, []);
});

test('retries until success and sleeps delayMs between attempts only', async () => {
  const { sleep, calls } = fakeSleep();
  const { operation, callCount } = failingTimes(2);

  const value = await retry(operation, { attempts: 5, delayMs: 100, sleep, shouldRetry: () => true });

  assert.equal(value, 'ok after 3');
  assert.equal(callCount(), 3);
  assert.deepEqual(calls, [100, 100]);
});

test('throws the last error object unchanged after exhausting attempts', async () => {
  const { sleep, calls } = fakeSleep();
  const errors = [new Error('first'), new Error('second'), new Error('last')];
  let index = 0;
  const operation = async () => {
    const error = errors[index];
    index += 1;
    throw error;
  };

  await assert.rejects(
    retry(operation, { attempts: 3, delayMs: 10, sleep, shouldRetry: () => true }),
    (error) => error === errors[2],
  );
  assert.equal(index, 3);
  assert.deepEqual(calls, [10, 10]);
});

test('does not sleep after the final failed attempt', async () => {
  const { sleep, calls } = fakeSleep();
  const { operation } = failingTimes(Infinity);

  await assert.rejects(retry(operation, { attempts: 1, delayMs: 10, sleep, shouldRetry: () => true }));
  assert.deepEqual(calls, []);
});

test('stops immediately when shouldRetry returns false', async () => {
  const { sleep, calls } = fakeSleep();
  const fatal = new Error('fatal');
  let invocations = 0;
  const seen = [];

  await assert.rejects(
    retry(async () => {
      invocations += 1;
      throw fatal;
    }, {
      attempts: 5,
      delayMs: 10,
      sleep,
      shouldRetry: (error) => {
        seen.push(error);
        return false;
      },
    }),
    (error) => error === fatal,
  );

  assert.equal(invocations, 1);
  assert.deepEqual(seen, [fatal]);
  assert.deepEqual(calls, []);
});

test('stops at a non-retryable error that appears after retries', async () => {
  const { sleep, calls } = fakeSleep();
  const transient = new Error('transient');
  const fatal = new Error('fatal');
  const errors = [transient, transient, fatal, transient];
  let index = 0;

  await assert.rejects(
    retry(async () => {
      const error = errors[index];
      index += 1;
      throw error;
    }, { attempts: 10, delayMs: 5, sleep, shouldRetry: (error) => error === transient }),
    (error) => error === fatal,
  );

  assert.equal(index, 3);
  assert.deepEqual(calls, [5, 5]);
});

test('makes a single call and never sleeps when attempts is 1', async () => {
  const { sleep, calls } = fakeSleep();
  const error = new Error('once');
  let invocations = 0;

  await assert.rejects(
    retry(async () => {
      invocations += 1;
      throw error;
    }, { attempts: 1, delayMs: 10, sleep, shouldRetry: () => true }),
    (thrown) => thrown === error,
  );

  assert.equal(invocations, 1);
  assert.deepEqual(calls, []);
});

test('passes delayMs through to sleep for every retry', async () => {
  const { sleep, calls } = fakeSleep();
  const { operation } = failingTimes(3);

  await retry(operation, { attempts: 4, delayMs: 25, sleep, shouldRetry: () => true });

  assert.deepEqual(calls, [25, 25, 25]);
});

test('rejects with RangeError for invalid attempts without calling the operation', async () => {
  const invalid = [0, -1, 1.5, NaN, Infinity, '3', null, undefined];

  for (const attempts of invalid) {
    const { sleep, calls } = fakeSleep();
    let invocations = 0;
    await assert.rejects(
      retry(async () => {
        invocations += 1;
        return 'never';
      }, { attempts, delayMs: 0, sleep, shouldRetry: () => true }),
      RangeError,
      `attempts=${String(attempts)} should be rejected`,
    );
    assert.equal(invocations, 0);
    assert.deepEqual(calls, []);
  }
});

async function retry(operation, { attempts, delayMs, sleep, shouldRetry }) {
  if (!Number.isInteger(attempts) || attempts < 1) {
    throw new RangeError("attempts must be a positive integer");
  }

  for (let attempt = 1; ; attempt += 1) {
    try {
      return await operation();
    } catch (error) {
      if (attempt >= attempts || !shouldRetry(error)) {
        throw error;
      }
      await sleep(delayMs);
    }
  }
}

