const { test } = require('node:test');
const assert = require('node:assert/strict');
const { retry } = require('../src/solution.cjs');

function scripted(steps) {
  const state = { calls: 0 };
  const operation = async () => {
    const step = steps[state.calls++];
    if ('fail' in step) throw step.fail;
    return step.ok;
  };
  return { operation, state };
}

function fakeSleep() {
  const delays = [];
  const sleep = async (ms) => {
    delays.push(ms);
  };
  return { sleep, delays };
}

test('returns the first successful value without sleeping', async () => {
  const { operation, state } = scripted([{ ok: 'done' }]);
  const { sleep, delays } = fakeSleep();

  const value = await retry(operation, { attempts: 3, delayMs: 50, sleep });

  assert.equal(value, 'done');
  assert.equal(state.calls, 1);
  assert.deepEqual(delays, []);
});

test('retries until success and sleeps only between attempts', async () => {
  const { operation, state } = scripted([
    { fail: new Error('first') },
    { fail: new Error('second') },
    { ok: 'third' },
  ]);
  const { sleep, delays } = fakeSleep();

  const value = await retry(operation, { attempts: 3, delayMs: 25, sleep });

  assert.equal(value, 'third');
  assert.equal(state.calls, 3);
  assert.deepEqual(delays, [25, 25]);
});

test('throws the last error object unchanged after exhausting attempts', async () => {
  const errors = [new Error('one'), new Error('two'), new Error('three')];
  const { operation, state } = scripted(errors.map((fail) => ({ fail })));
  const { sleep, delays } = fakeSleep();

  await assert.rejects(
    retry(operation, { attempts: 3, delayMs: 10, sleep }),
    (error) => error === errors[2],
  );
  assert.equal(state.calls, 3);
  assert.deepEqual(delays, [10, 10]);
});

test('a single attempt calls once, throws the error, and never sleeps', async () => {
  const failure = new Error('only');
  const { operation, state } = scripted([{ fail: failure }]);
  const { sleep, delays } = fakeSleep();

  await assert.rejects(
    retry(operation, { attempts: 1, delayMs: 10, sleep }),
    (error) => error === failure,
  );
  assert.equal(state.calls, 1);
  assert.deepEqual(delays, []);
});

test('stops immediately when shouldRetry returns false', async () => {
  const fatal = Object.assign(new Error('fatal'), { retryable: false });
  const { operation, state } = scripted([{ fail: fatal }, { ok: 'unreachable' }]);
  const { sleep, delays } = fakeSleep();

  await assert.rejects(
    retry(operation, {
      attempts: 5,
      delayMs: 10,
      sleep,
      shouldRetry: (error) => error.retryable === true,
    }),
    (error) => error === fatal,
  );
  assert.equal(state.calls, 1);
  assert.deepEqual(delays, []);
});

test('consults shouldRetry per error and retries only matching errors', async () => {
  const transient = Object.assign(new Error('transient'), { retryable: true });
  const fatal = Object.assign(new Error('fatal'), { retryable: false });
  const { operation, state } = scripted([
    { fail: transient },
    { fail: fatal },
    { ok: 'unreachable' },
  ]);
  const { sleep, delays } = fakeSleep();
  const seen = [];

  await assert.rejects(
    retry(operation, {
      attempts: 5,
      delayMs: 10,
      sleep,
      shouldRetry: (error) => {
        seen.push(error);
        return error.retryable;
      },
    }),
    (error) => error === fatal,
  );
  assert.deepEqual(seen, [transient, fatal]);
  assert.equal(state.calls, 2);
  assert.deepEqual(delays, [10]);
});

test('does not consult shouldRetry after the final attempt', async () => {
  const { operation, state } = scripted([
    { fail: new Error('a') },
    { fail: new Error('b') },
  ]);
  const { sleep, delays } = fakeSleep();
  let consulted = 0;

  await assert.rejects(
    retry(operation, {
      attempts: 2,
      delayMs: 5,
      sleep,
      shouldRetry: () => {
        consulted += 1;
        return true;
      },
    }),
    /b/,
  );
  assert.equal(state.calls, 2);
  assert.equal(consulted, 1);
  assert.deepEqual(delays, [5]);
});

test('rejects with RangeError for invalid attempts without calling the operation', async () => {
  for (const attempts of [0, -1, 1.5, NaN, Infinity, '3', null, undefined]) {
    const { operation, state } = scripted([{ ok: 'value' }]);
    const { sleep, delays } = fakeSleep();

