import sqlite3

MIN_LIMIT = 1
MAX_LIMIT = 100

_SEARCH_SQL = (
    "SELECT id, name FROM users "
    "WHERE name LIKE ? ESCAPE '\\' "
    "ORDER BY name, id "
    "LIMIT ?"
)


def _escape_like(text):
    # 反斜杠必须最先转义，否则会重复转义后面插入的 '\'
    return text.replace("\\", "\\\\").replace("%", "\\%").replace("_", "\\_")


def _validate_limit(limit):
    if isinstance(limit, bool) or not isinstance(limit, int):
        raise ValueError("limit must be an int")
    return min(max(limit, MIN_LIMIT), MAX_LIMIT)


def search(conn, name_prefix, limit):
    if not isinstance(name_prefix, str):
        raise ValueError("name_prefix must be a str")
    pattern = _escape_like(name_prefix) + "%"
    return conn.execute(_SEARCH_SQL, (pattern, _validate_limit(limit))).fetchall()

import sqlite3

MIN_LIMIT = 1
MAX_LIMIT = 100
LIKE_ESCAPE = "\\"


def _escape_like(text: str) -> str:
    # 必须先转义反斜杠，否则为 % 和 _ 添加的转义符会被再次转义
    escaped = text.replace(LIKE_ESCAPE, LIKE_ESCAPE * 2)
    return escaped.replace("%", LIKE_ESCAPE + "%").replace("_", LIKE_ESCAPE + "_")


def _checked_limit(limit: object) -> int:
    if type(limit) is not int:
        raise ValueError("limit must be an int")
    return min(max(limit, MIN_LIMIT), MAX_LIMIT)


def search(conn: sqlite3.Connection, name_prefix: str, limit: int) -> list[tuple[int, str]]:
    if not isinstance(name_prefix, str):
        raise TypeError("name_prefix must be a str")
    pattern = _escape_like(name_prefix) + "%"
    return conn.execute(
        "SELECT id, name FROM users WHERE name LIKE ? ESCAPE '\\' ORDER BY name, id LIMIT ?",
        (pattern, _checked_limit(limit)),
    ).fetchall()

