        self.assertEqual(search(self.conn, "al", 100), [(2, "alan"), (1, "alice"), (10, "alice")])

    def test_percent_is_literal(self):
        self.assertEqual(search(self.conn, "100%", 100), [(4, "100% pure")])

    def test_underscore_is_literal(self):
        self.assertEqual(search(self.conn, "a_", 100), [(6, "a_b")])

