import csv
import io
import re

_AGE_PATTERN = re.compile(r"[0-9]+")
_MAX_AGE = 130


def read_people(text):
    reader = csv.reader(io.StringIO(text, newline=""), strict=True)
    try:
        header = next(reader, None)
        if header != ["name", "age"]:
            raise ValueError(f"unexpected header: {header!r}")
        return [_parse_row(row, reader.line_num) for row in reader]
    except csv.Error as exc:
        raise ValueError(f"invalid CSV: {exc}") from exc


def _parse_row(row, line_num):
    if len(row) != 2:
        raise ValueError(f"line {line_num}: expected 2 columns, got {len(row)}")
    name, age_text = row
    return {"name": name, "age": _parse_age(age_text, line_num)}


def _parse_age(text, line_num):
    if not _AGE_PATTERN.fullmatch(text):
        raise ValueError(f"line {line_num}: age must be ASCII digits, got {text!r}")
    age = int(text)
    if age > _MAX_AGE:
        raise ValueError(f"line {line_num}: age must be 0..{_MAX_AGE}, got {age}")
    return age

