HEADER = ["name", "age"]
AGE_DIGITS = re.compile(r"[0-9]+")
MIN_AGE = 0
MAX_AGE = 130


# ==================== 对外入口 ====================
def read_people(text):
    rows = _parse_csv(text)
    if not rows or rows[0] != HEADER:
        raise ValueError("表头必须严格为 name,age")
    return [_parse_person(row, no) for no, row in enumerate(rows[1:], start=2)]


# ==================== CSV 解析 ====================
def _parse_csv(text):
    try:
        return list(csv.reader(io.StringIO(text, newline=""), strict=True))
    except csv.Error as exc:
        raise ValueError(f"CSV 引号或格式错误: {exc}") from exc


def _parse_person(row, record_no):
    if len(row) != 2:
        raise ValueError(f"第 {record_no} 条记录应为 2 列，实际为 {len(row)} 列")
    name, raw_age = row
    return {"name": name, "age": _parse_age(raw_age, record_no)}


# ==================== 年龄校验 ====================
def _parse_age(raw, record_no):
    if not AGE_DIGITS.fullmatch(raw):
        raise ValueError(f"第 {record_no} 条记录的年龄 {raw!r} 不是纯 ASCII 数字")
    age = int(raw)
    if not MIN_AGE <= age <= MAX_AGE:
        raise ValueError(f"第 {record_no} 条记录的年龄 {age} 超出 {MIN_AGE}..{MAX_AGE}")
    return age

