_HEADER = ["name", "age"]
_DIGITS = frozenset("0123456789")
_MAX_AGE = 130


def read_people(text):
    try:
        rows = csv.reader(io.StringIO(text, newline=""), strict=True)
        header = next(rows, None)
        if header is None:
            raise ValueError("missing header")
        if header != _HEADER:
            raise ValueError(f"unexpected header: {header!r}")
