                )
            name, age = row
            people.append({"name": name, "age": _parse_age(age, rows.line_num)})
    except csv.Error as exc:
        raise ValueError(f"invalid CSV: {exc}") from exc
    return people


def _parse_age(text, line_num):
    if not text or not all(ch in _DIGITS for ch in text):
        raise ValueError(f"line {line_num}: invalid age {text!r}")
    age = int(text)
    if age > _MAX_AGE:
        raise ValueError(f"line {line_num}: age {age} out of range 0..{_MAX_AGE}")
    return age

