    def test_missing_column_is_rejected(self):
        with self.assertRaises(ValueError):
            read_people("name,age\nAnn\n")

    def test_extra_column_is_rejected(self):
        with self.assertRaises(ValueError):
            read_people("name,age\nAnn,1,extra\n")

    def test_blank_line_in_data_is_rejected(self):
        with self.assertRaises(ValueError):
            read_people("name,age\nAnn,1\n\nBob,2\n")

    def test_quoted_field_then_extra_text_is_rejected(self):
        with self.assertRaises(ValueError):
            read_people('name,age\n"abc"def,3\n')

    def test_unterminated_quote_is_rejected(self):
        with self.assertRaises(ValueError):
            read_people('name,age\n"Ann,3\n')

    def test_stray_quote_in_unquoted_field_is_rejected(self):
        with self.assertRaises(ValueError):
            read_people('name,age\nAn"n,3\n')

    def test_invalid_ages_are_rejected(self):
        bad_ages = ["", " 3", "3 ", "-1", "+5", "3.5", "1e2", "abc", "0x1", "131", "1000", "٣"]
        for age in bad_ages:
