async function collectPages(fetchPage) {
  const items = [];
  const seenCursors = new Set();
  let cursor = null;

  for (;;) {
    const page = await fetchPage(cursor);
    for (const item of page.items) {
      items.push(item);
    }
    if (page.next === null) {
      return items;
    }
    if (seenCursors.has(page.next)) {
      throw new Error(`游标被重复请求: ${JSON.stringify(page.next)}`);
    }
    seenCursors.add(page.next);
    cursor = page.next;
  }
}

