// 仅以 next === null 作为结束信号；重复游标直接报错，避免死循环

async function collectPages(fetchPage) {
  const items = [];
  const seenCursors = new Set();
  let cursor = null;

  for (;;) {
    if (cursor !== null) {
      if (seenCursors.has(cursor)) {
        throw new Error(`Cursor requested twice: ${JSON.stringify(cursor)}`);
      }
      seenCursors.add(cursor);
    }

    const page = await fetchPage(cursor);
    for (const item of page.items) {
      items.push(item);
    }

    if (page.next === null) {
      return items;
    }
    cursor = page.next;
  }
}

