'use strict';

// ==================== 基础判定 ====================
const UNSAFE_KEYS = new Set(['__proto__', 'constructor', 'prototype']);

function isPlainObject(value) {
  if (value === null || typeof value !== 'object') return false;
  const proto = Object.getPrototypeOf(value);
  return proto === Object.prototype || proto === null;
}

function isObjectLike(value) {
  return value !== null && (typeof value === 'object' || typeof value === 'function');
}

// ==================== 输入校验：整棵树递归检查 ====================
function assertJsonLike(value) {
  if (Array.isArray(value)) {
    value.forEach((item) => assertJsonLike(item));
  } else if (isPlainObject(value)) {
    for (const key of Object.getOwnPropertyNames(value)) {
      if (UNSAFE_KEYS.has(key)) throw new TypeError(`Unsafe key "${key}" is not allowed`);
    }
    for (const key of Object.keys(value)) assertJsonLike(value[key]);
  } else if (isObjectLike(value)) {
    throw new TypeError('Unsupported value: only plain objects, arrays and scalars are allowed');
  }
}

// ==================== 深拷贝：切断与输入的所有引用 ====================
function deepCopy(value) {
  if (Array.isArray(value)) return value.map((item) => deepCopy(item));
  if (!isPlainObject(value)) return value;
  const copy = {};
  for (const key of Object.keys(value)) copy[key] = deepCopy(value[key]);
  return copy;
}

// ==================== 合并：仅普通对象递归，其余整体替换 ====================
function mergeValues(base, override) {
  if (!isPlainObject(base) || !isPlainObject(override)) return deepCopy(override);
  const result = deepCopy(base);
  for (const key of Object.keys(override)) {
    const baseValue = Object.hasOwn(base, key) ? base[key] : undefined;
    result[key] = mergeValues(baseValue, override[key]);
  }
  return result;
}

function mergeConfig(base, override) {
  assertJsonLike(base);
  assertJsonLike(override);
  return mergeValues(base, override);
}

module.exports = { mergeConfig };

'use strict';

const { test } = require('node:test');
const assert = require('node:assert/strict');
const { mergeConfig } = require('../src/solution.cjs');

// ==================== 辅助：收集所有对象/数组引用 ====================
function collectContainers(value, set = new Set()) {
  if (value === null || typeof value !== 'object') return set;
  set.add(value);
  for (const key of Object.keys(value)) collectContainers(value[key], set);
  return set;
}

function sharesContainer(a, b) {
  const left = collectContainers(a);
  for (const container of collectContainers(b)) {
    if (left.has(container)) return true;
  }
  return false;
}

