test('merges nested plain objects recursively', () => {
  const base = { a: { b: 1, c: { d: 2 } }, keep: { x: 1 } };
  const override = { a: { c: { e: 3 } }, added: true };
  assert.deepStrictEqual(mergeConfig(base, override), {
