'use strict';

const UNSAFE_KEYS = new Set(['__proto__', 'constructor', 'prototype']);
const SCALAR_TYPES = new Set(['string', 'number', 'boolean']);

function isPlainObject(value) {
  if (value === null || typeof value !== 'object' || Array.isArray(value)) return false;
  const proto = Object.getPrototypeOf(value);
  return proto === Object.prototype || proto === null;
}

function assertSafeKeys(container, path) {
  for (const key of Reflect.ownKeys(container)) {
    if (UNSAFE_KEYS.has(key)) throw new Error(`禁止的键 "${key}"，位置：${path}`);
  }
}

function assertJsonLike(value, path) {
  if (value === null || SCALAR_TYPES.has(typeof value)) return;

  if (Array.isArray(value)) {
    assertSafeKeys(value, path);
    for (let i = 0; i < value.length; i++) assertJsonLike(value[i], `${path}[${i}]`);
    return;
  }

  if (!isPlainObject(value)) throw new TypeError(`不是 JSON 类值，位置：${path}`);
  assertSafeKeys(value, path);
  for (const key of Object.keys(value)) assertJsonLike(value[key], `${path}.${key}`);
}

function cloneValue(value) {
  if (Array.isArray(value)) return value.map(cloneValue);
  if (!isPlainObject(value)) return value;

  const copy = {};
  for (const key of Object.keys(value)) copy[key] = cloneValue(value[key]);
  return copy;
}

function mergeValues(base, override) {
  if (!isPlainObject(base) || !isPlainObject(override)) return cloneValue(override);

  const result = {};
  for (const key of Object.keys(base)) {
    result[key] = Object.hasOwn(override, key)
      ? mergeValues(base[key], override[key])
      : cloneValue(base[key]);
  }
  for (const key of Object.keys(override)) {
    if (!Object.hasOwn(base, key)) result[key] = cloneValue(override[key]);
  }
  return result;
}

function mergeConfig(base, override) {
  assertJsonLike(base, 'base');
  assertJsonLike(override, 'override');
  return mergeValues(base, override);
}

module.exports = { mergeConfig };

