'use strict';

const UNSAFE_KEYS = new Set(['__proto__', 'constructor', 'prototype']);

function isPlainObject(value) {
  if (value === null || typeof value !== 'object' || Array.isArray(value)) {
    return false;
  }
  const proto = Object.getPrototypeOf(value);
  return proto === Object.prototype || proto === null;
}

function assertJsonLike(value) {
  if (value === null || typeof value === 'string' || typeof value === 'boolean') {
    return;
  }
  if (typeof value === 'number') {
    return;
  }
  if (Array.isArray(value)) {
    for (const item of value) {
      assertJsonLike(item);
    }
    return;
  }
  if (isPlainObject(value)) {
    for (const key of Object.keys(value)) {
      if (UNSAFE_KEYS.has(key)) {
        throw new TypeError(`Unsafe key "${key}" is not allowed`);
      }
      assertJsonLike(value[key]);
    }
    return;
  }
  throw new TypeError(`Unsupported value of type ${typeof value} in config`);
}

function deepCopy(value) {
  if (Array.isArray(value)) {
    return value.map(deepCopy);
  }
  if (isPlainObject(value)) {
    const copy = {};
    for (const key of Object.keys(value)) {
      copy[key] = deepCopy(value[key]);
    }
    return copy;
  }
  return value;
}

function mergeObjects(base, override) {
  const result = {};
  for (const key of Object.keys(base)) {
    result[key] = deepCopy(base[key]);
  }
  for (const key of Object.keys(override)) {
    const overrideValue = override[key];
    if (isPlainObject(overrideValue) && isPlainObject(base[key])) {
      result[key] = mergeObjects(base[key], overrideValue);
    } else {
      result[key] = deepCopy(overrideValue);
    }
  }
  return result;
}

function mergeConfig(base, override) {
  if (!isPlainObject(base) || !isPlainObject(override)) {
    throw new TypeError('mergeConfig expects two plain objects');
  }
  assertJsonLike(base);
  assertJsonLike(override);
  return mergeObjects(base, override);
}

module.exports = { mergeConfig };

