'use strict';

// ==================== 输入校验 ====================
function assertValidInput(total, weights) {
  if (!Number.isSafeInteger(total) || total < 0) {
    throw new RangeError('total must be a nonnegative safe integer');
  }
  if (!Array.isArray(weights) || weights.length === 0) {
    throw new RangeError('weights must be a nonempty array');
  }
  for (const weight of weights) {
    if (!Number.isSafeInteger(weight) || weight <= 0) {
      throw new RangeError('weights must contain only positive safe integers');
    }
    if (!Number.isSafeInteger(total * weight)) {
      throw new RangeError('total * weight must be a safe integer');
    }
  }
  if (!Number.isSafeInteger(weights.reduce((sum, weight) => sum + weight, 0))) {
    throw new RangeError('sum of weights must be a safe integer');
  }
}

// ==================== 最大余数法 ====================
function byLargestRemainder(a, b) {
  if (a.remainder !== b.remainder) return a.remainder > b.remainder ? -1 : 1;
  return a.index - b.index;
}

function splitCents(total, weights) {
  assertValidInput(total, weights);

  const weightSum = BigInt(weights.reduce((sum, weight) => sum + weight, 0));
  const shares = weights.map((weight, index) => {
    const numerator = BigInt(total) * BigInt(weight);
    return { index, cents: numerator / weightSum, remainder: numerator % weightSum };
  });

  const allocated = shares.reduce((sum, share) => sum + share.cents, 0n);
  const leftover = Number(BigInt(total) - allocated);

  shares
    .slice()
    .sort(byLargestRemainder)
    .slice(0, leftover)
    .forEach((share) => {
      share.cents += 1n;
    });

  return shares.map((share) => Number(share.cents));
}

module.exports = { splitCents };

'use strict';

const { test } = require('node:test');
const assert = require('node:assert/strict');
const { splitCents } = require('../src/solution.cjs');

const sum = (values) => values.reduce((acc, value) => acc + value, 0);

test('ties: equal remainders give leftover cents to earlier indices', () => {
  assert.deepEqual(splitCents(10, [1, 1, 1]), [4, 3, 3]);
  assert.deepEqual(splitCents(5, [1, 1]), [3, 2]);
  assert.deepEqual(splitCents(100, [3, 3, 3]), [34, 33, 33]);
});

test('largest remainder wins even when it is at a later index', () => {
  // quotas 2.33 (rem 1/3) and 4.67 (rem 2/3): the leftover cent goes to index 1
  assert.deepEqual(splitCents(7, [1, 2]), [2, 5]);
  // quotas 4.67 (rem 2/3) and 2.33 (rem 1/3): the leftover cent goes to index 0
  assert.deepEqual(splitCents(7, [2, 1]), [5, 2]);
});

