'use strict';

const MAX_SAFE = BigInt(Number.MAX_SAFE_INTEGER);

function invalid(message) {
  return new RangeError(`splitCents: ${message}`);
}

function validate(total, weights) {
  if (!Number.isSafeInteger(total) || total < 0) {
    throw invalid('total must be a nonnegative safe integer');
  }
  if (!Array.isArray(weights) || weights.length === 0) {
    throw invalid('weights must be a nonempty array');
  }

  let sum = 0n;
  for (const w of weights) {
    if (!Number.isSafeInteger(w) || w <= 0) {
      throw invalid('weights must be positive safe integers');
    }
    sum += BigInt(w);
  }
  if (sum > MAX_SAFE) {
    throw invalid('sum of weights exceeds safe integer range');
  }

  const t = BigInt(total);
  for (const w of weights) {
    if (t * BigInt(w) > MAX_SAFE) {
      throw invalid('total * weight exceeds safe integer range');
    }
  }
}

function byRemainderDesc(a, b) {
  if (a.rem !== b.rem) return a.rem > b.rem ? -1 : 1;
  return a.index - b.index;
}

function splitCents(total, weights) {
  validate(total, weights);

  const t = BigInt(total);
  const ws = weights.map((w) => BigInt(w));
  const sum = ws.reduce((acc, w) => acc + w, 0n);

  const parts = ws.map((w, index) => {
    const numerator = t * w;
    return { index, floor: numerator / sum, rem: numerator % sum };
  });

  let leftover = t - parts.reduce((acc, p) => acc + p.floor, 0n);
  for (const p of [...parts].sort(byRemainderDesc)) {
    if (leftover === 0n) break;
    p.floor += 1n;
    leftover -= 1n;
  }

  return parts.map((p) => Number(p.floor));
}

module.exports = { splitCents };

