const MAX_SAFE = Number.MAX_SAFE_INTEGER;

function invalid(message) {
  return new RangeError(`splitCents: ${message}`);
}

function validate(total, weights) {
  if (!Number.isSafeInteger(total) || total < 0) {
    throw invalid('total must be a nonnegative safe integer');
  }
  if (!Array.isArray(weights) || weights.length === 0) {
    throw invalid('weights must be a nonempty array');
  }

  let sum = 0;
  for (const weight of weights) {
    if (!Number.isSafeInteger(weight) || weight <= 0) {
      throw invalid('weights must contain only positive safe integers');
    }
    if (weight > MAX_SAFE - sum) {
      throw invalid('sum of weights exceeds safe integer range');
    }
    sum += weight;
    if (!Number.isSafeInteger(total * weight)) {
      throw invalid('total * weight exceeds safe integer range');
    }
  }
}

function splitCents(total, weights) {
  validate(total, weights);

  const totalBig = BigInt(total);
  const weightBig = weights.map(BigInt);
  const weightSum = weightBig.reduce((acc, w) => acc + w, 0n);
  const products = weightBig.map((w) => totalBig * w);

  const shares = products.map((p) => p / weightSum);
  const remainders = products.map((p) => p % weightSum);

  const leftover = Number(totalBig - shares.reduce((acc, s) => acc + s, 0n));

  // 余数大者优先多分一分，余数相同则索引小者优先
  const order = weights
    .map((_, index) => index)
    .sort((a, b) => {
      if (remainders[a] !== remainders[b]) return remainders[a] > remainders[b] ? -1 : 1;
      return a - b;
    });

  for (const index of order.slice(0, leftover)) {
    shares[index] += 1n;
  }

  return shares.map(Number);
}

module.exports = { splitCents };

