'use strict';

function splitCents(total, weights) {
  if (!Number.isSafeInteger(total) || total < 0) {
    throw new RangeError('total must be a nonnegative safe integer');
  }
  if (!Array.isArray(weights) || weights.length === 0) {
    throw new RangeError('weights must be a nonempty array');
  }

  let weightSum = 0;
  for (const weight of weights) {
    if (!Number.isSafeInteger(weight) || weight <= 0) {
      throw new RangeError('weights must contain positive safe integers');
    }
    weightSum += weight;
    if (!Number.isSafeInteger(weightSum) || !Number.isSafeInteger(total * weight)) {
      throw new RangeError('sum of weights and total * weight must be safe integers');
    }
  }

  const bigTotal = BigInt(total);
  const bigSum = BigInt(weightSum);
  const shares = weights.map((weight, index) => {
    const product = bigTotal * BigInt(weight);
    return { index, floor: product / bigSum, remainder: product % bigSum };
  });

  const allocated = shares.reduce((acc, share) => acc + share.floor, 0n);
  let leftover = Number(bigTotal - allocated);

  const byRemainder = shares.slice().sort((a, b) => {
    if (a.remainder !== b.remainder) return a.remainder > b.remainder ? -1 : 1;
    return a.index - b.index;
  });
  for (let i = 0; i < leftover; i++) {
    byRemainder[i].floor += 1n;
  }

  return shares.map((share) => Number(share.floor));
}

