const MAX_SAFE = BigInt(Number.MAX_SAFE_INTEGER);

function splitCents(total, weights) {
  if (!Number.isSafeInteger(total) || total < 0) {
    throw new RangeError('total must be a nonnegative safe integer');
  }
  if (!Array.isArray(weights) || weights.length === 0) {
    throw new RangeError('weights must be a nonempty array');
  }

  const t = BigInt(total);
  let weightSum = 0n;
  for (let i = 0; i < weights.length; i++) {
    const w = weights[i];
    if (!Number.isSafeInteger(w) || w <= 0) {
      throw new RangeError(`weights[${i}] must be a positive safe integer`);
    }
    const bw = BigInt(w);
    if (t * bw > MAX_SAFE) {
      throw new RangeError(`total * weights[${i}] exceeds the safe integer range`);
    }
    weightSum += bw;
  }
  if (weightSum > MAX_SAFE) {
    throw new RangeError('sum of weights exceeds the safe integer range');
  }

  const shares = new Array(weights.length);
  const remainders = new Array(weights.length);
  let allocated = 0n;
  for (let i = 0; i < weights.length; i++) {
    const product = t * BigInt(weights[i]);
    shares[i] = product / weightSum;
    remainders[i] = product % weightSum;
    allocated += shares[i];
  }

  const leftover = Number(t - allocated);
  const order = weights.map((_, i) => i).sort((a, b) => {
    if (remainders[a] !== remainders[b]) return remainders[a] > remainders[b] ? -1 : 1;
    return a - b;
  });
  for (let k = 0; k < leftover; k++) {
    shares[order[k]] += 1n;
  }

  return shares.map(Number);
}

