'use strict';

function splitCents(total, weights) {
  if (!Number.isSafeInteger(total) || total < 0) {
    throw new RangeError('total must be a nonnegative safe integer');
  }
  if (!Array.isArray(weights) || weights.length === 0) {
    throw new RangeError('weights must be a nonempty array');
  }

  let weightSum = 0;
  for (const weight of weights) {
    if (!Number.isSafeInteger(weight) || weight < 1) {
      throw new RangeError('each weight must be a positive safe integer');
    }
    weightSum += weight;
    if (!Number.isSafeInteger(weightSum)) {
      throw new RangeError('sum of weights must be a safe integer');
    }
  }

  const products = weights.map((weight) => {
    const product = total * weight;
    if (!Number.isSafeInteger(product)) {
      throw new RangeError('total * weight must be a safe integer');
    }
    return product;
  });

  const result = new Array(weights.length);
  const remainders = new Array(weights.length);
  let allocated = 0;
  for (let i = 0; i < weights.length; i++) {
    const remainder = products[i] % weightSum;
    result[i] = (products[i] - remainder) / weightSum;
    remainders[i] = remainder;
    allocated += result[i];
  }

  const leftover = total - allocated;
  const order = weights
    .map((_, i) => i)
    .sort((a, b) => remainders[b] - remainders[a] || a - b);
  for (let k = 0; k < leftover; k++) {
    result[order[k]] += 1;
  }

  return result;
}

