'use strict';

const MAX_SAFE = BigInt(Number.MAX_SAFE_INTEGER);

function splitCents(total, weights) {
  if (!Number.isSafeInteger(total) || total < 0) {
    throw new RangeError('total must be a nonnegative safe integer');
  }
  if (!Array.isArray(weights) || weights.length === 0) {
    throw new RangeError('weights must be a nonempty array');
  }

  let sum = 0n;
  for (const weight of weights) {
    if (!Number.isSafeInteger(weight) || weight <= 0) {
      throw new RangeError('weights must be positive safe integers');
    }
    if (!Number.isSafeInteger(total * weight)) {
      throw new RangeError('total * weight must be a safe integer');
    }
    sum += BigInt(weight);
  }
  if (sum > MAX_SAFE) {
    throw new RangeError('sum of weights must be a safe integer');
  }

  // BigInt keeps quota and remainder exact; Number division can misround near 2^53.
  const t = BigInt(total);
  const parts = weights.map((weight, index) => {
    const product = t * BigInt(weight);
    return { index, base: product / sum, remainder: product % sum };
  });

  const allocated = parts.reduce((acc, part) => acc + part.base, 0n);
  const leftover = Number(t - allocated);

  const byRemainder = [...parts].sort((a, b) => {
    if (a.remainder !== b.remainder) return a.remainder > b.remainder ? -1 : 1;
    return a.index - b.index;
  });
  for (let i = 0; i < leftover; i++) {
    byRemainder[i].base += 1n;
  }

  return parts.map((part) => Number(part.base));
}

