from datetime import datetime, time, timezone


def utc_day_start(text):
    if not isinstance(text, str):
        raise ValueError(f"timestamp must be a string, got {type(text).__name__}")

    # Python 3.9's fromisoformat does not accept the "Z" designator
    normalized = text[:-1] + "+00:00" if text.endswith("Z") else text
    try:
        instant = datetime.fromisoformat(normalized)
    except ValueError as exc:
        raise ValueError(f"invalid ISO 8601 timestamp: {text!r}") from exc

    if instant.utcoffset() is None:
        raise ValueError(f"timestamp must carry a UTC offset: {text!r}")

    try:
        day = instant.astimezone(timezone.utc).date()
    except OverflowError as exc:
        raise ValueError(f"timestamp is out of range in UTC: {text!r}") from exc

    return datetime.combine(day, time.min, tzinfo=timezone.utc)

