from datetime import datetime, timezone


def utc_day_start(text):
    if not isinstance(text, str):
        raise ValueError("timestamp must be a string")
    # Python 3.9 fromisoformat does not accept a trailing Z
    value = text[:-1] + "+00:00" if text.endswith("Z") else text
    try:
        instant = datetime.fromisoformat(value)
    except ValueError:
        raise ValueError(f"invalid ISO 8601 timestamp: {text!r}") from None
    if instant.utcoffset() is None:
        raise ValueError(f"timestamp must include a UTC offset: {text!r}")
    try:
        utc = instant.astimezone(timezone.utc)
    except OverflowError:
        raise ValueError(f"timestamp out of range when converted to UTC: {text!r}") from None
    return datetime(utc.year, utc.month, utc.day, tzinfo=timezone.utc)

