TWO_BYTE = "é".encode("utf-8")  # C3 A9
THREE_BYTE = "€".encode("utf-8")  # E2 82 AC
FOUR_BYTE = "😀".encode("utf-8")  # F0 9F 98 80


class DecodeChunksTest(unittest.TestCase):
    def test_empty_iterable(self):
        self.assertEqual(decode_chunks([]), "")

    def test_empty_chunks_are_ignored(self):
        self.assertEqual(decode_chunks([b"", b"a", b"", b"b", b""]), "ab")

    def test_ascii_single_chunk(self):
        self.assertEqual(decode_chunks([b"hello"]), "hello")

    def test_multibyte_split_at_every_boundary(self):
        for char in ("é", "€", "😀"):
            data = char.encode("utf-8")
            for i in range(1, len(data)):
                with self.subTest(char=char, split=i):
                    self.assertEqual(decode_chunks([data[:i], data[i:]]), char)

    def test_one_byte_per_chunk(self):
        text = "héllo €😀 world"
        data = text.encode("utf-8")
        chunks = [data[i : i + 1] for i in range(len(data))]
        self.assertEqual(decode_chunks(chunks), text)

    def test_multibyte_split_with_empty_chunks_between(self):
        chunks = [THREE_BYTE[:1], b"", THREE_BYTE[1:2], b"", THREE_BYTE[2:]]
        self.assertEqual(decode_chunks(chunks), "€")

    def test_accepts_lazy_generator(self):
        def gen():
            yield "a€".encode("utf-8")[:2]
            yield "a€".encode("utf-8")[2:]

        self.assertEqual(decode_chunks(gen()), "a€")

    def test_incomplete_final_character_raises(self):
        with self.assertRaises(UnicodeDecodeError):
            decode_chunks([b"abc", THREE_BYTE[:2]])

    def test_incomplete_final_character_single_byte_raises(self):
        with self.assertRaises(UnicodeDecodeError):
            decode_chunks([TWO_BYTE[:1]])

    def test_incomplete_four_byte_at_end_raises(self):
        with self.assertRaises(UnicodeDecodeError):
            decode_chunks([FOUR_BYTE[:3]])

    def test_invalid_start_byte_raises(self):
        with self.assertRaises(UnicodeDecodeError):
            decode_chunks([b"ok", b"\xff", b"more"])

    def test_invalid_continuation_across_chunks_raises(self):
        with self.assertRaises(UnicodeDecodeError):
            decode_chunks([THREE_BYTE[:2], b"A"])

    def test_lone_continuation_byte_raises(self):
        with self.assertRaises(UnicodeDecodeError):
            decode_chunks([b"\x80"])

    def test_surrogate_encoding_raises(self):
        with self.assertRaises(UnicodeDecodeError):
            decode_chunks([b"\xed\xa0\x80"])

    def test_overlong_encoding_raises(self):
        with self.assertRaises(UnicodeDecodeError):
            decode_chunks([b"\xc0\xaf"])


