// ==================== 版本号格式 ====================
// 三段十进制非负整数，无前导零（单独的 0 除外），无符号、空格、后缀
const VERSION_PATTERN = /^(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)$/;

// ==================== 解析与校验 ====================
function parseVersion(version) {
  if (typeof version !== 'string') {
    throw new TypeError('版本号必须是字符串');
  }
  const match = VERSION_PATTERN.exec(version);
  if (match === null) {
    throw new TypeError(`非法版本号: ${JSON.stringify(version)}`);
  }
  return match.slice(1);
}

// ==================== 大整数比较 ====================
// 无前导零时，位数更多的数字一定更大，因此无需转换为数值即可比较
function compareComponent(a, b) {
  if (a.length !== b.length) {
    return a.length < b.length ? -1 : 1;
  }
  if (a === b) {
    return 0;
  }
  return a < b ? -1 : 1;
}

// ==================== 版本比较入口 ====================
function compareVersion(a, b) {
  const left = parseVersion(a);
  const right = parseVersion(b);
  for (let i = 0; i < 3; i++) {
    const result = compareComponent(left[i], right[i]);
    if (result !== 0) {
      return result;
    }
  }
  return 0;
}

module.exports = { compareVersion };

const { test } = require('node:test');
const assert = require('node:assert/strict');
const { compareVersion } = require('../src/solution.cjs');

test('按数值而非字典序比较各分量', () => {
  assert.equal(compareVersion('1.10.0', '1.2.9'), 1);
  assert.equal(compareVersion('1.2.9', '1.10.0'), -1);
});

test('依次比较主版本、次版本、修订号', () => {
  assert.equal(compareVersion('2.0.0', '1.9.9'), 1);
  assert.equal(compareVersion('1.3.0', '1.2.9'), 1);
  assert.equal(compareVersion('1.2.10', '1.2.9'), 1);
  assert.equal(compareVersion('1.2.3', '1.2.4'), -1);
});

test('相等版本返回 0', () => {
  assert.equal(compareVersion('0.0.0', '0.0.0'), 0);
  assert.equal(compareVersion('1.2.3', '1.2.3'), 0);
  assert.equal(compareVersion('0.0.1', '0.0.1'), 0);
});

test('超过 Number.MAX_SAFE_INTEGER 的分量仍能正确比较', () => {
  const beyondSafe = '9007199254740993';
  const safeEdge = '9007199254740992';
  assert.equal(compareVersion(`${beyondSafe}.0.0`, `${safeEdge}.0.0`), 1);
  assert.equal(compareVersion(`${safeEdge}.0.0`, `${beyondSafe}.0.0`), -1);
  assert.equal(compareVersion(`${beyondSafe}.0.0`, `${beyondSafe}.0.0`), 0);
});

test('位数不同的超大分量按位数判断大小', () => {
  assert.equal(compareVersion('10000000000000000000000.0.0', '9999999999999999999999.0.0'), 1);
  assert.equal(compareVersion('1.18446744073709551616.0', '1.18446744073709551615.999999'), 1);
  assert.equal(compareVersion('1.0.18446744073709551616', '1.0.18446744073709551616'), 0);
