class Emitter {
  #events = new Map();

  #listenersOf(event) {
    let listeners = this.#events.get(event);
    if (!listeners) {
      listeners = new Map();
      this.#events.set(event, listeners);
    }
    return listeners;
  }

  on(event, fn) {
    const listeners = this.#listenersOf(event);
    if (listeners.has(fn)) return listeners.get(fn);

    const unsubscribe = () => {
      if (listeners.get(fn) === unsubscribe) listeners.delete(fn);
    };
    listeners.set(fn, unsubscribe);
    return unsubscribe;
  }

  off(event, fn) {
    this.#events.get(event)?.delete(fn);
  }

  emit(event, value) {
    const listeners = this.#events.get(event);
    if (!listeners) return;
    for (const fn of [...listeners.keys()]) fn(value);
  }
}

