class Emitter {
  #events = new Map(); // event -> Map<fn, registration token>

  on(event, fn) {
    if (!this.#events.has(event)) this.#events.set(event, new Map());
    const listeners = this.#events.get(event);
    // 同一监听器在同一事件下只登记一次；重复登记沿用原凭证，取消函数始终只撤销它所属的那次登记
    if (!listeners.has(fn)) listeners.set(fn, {});
    const token = listeners.get(fn);
    return () => {
      if (this.#events.get(event)?.get(fn) === token) this.off(event, fn);
    };
  }

  off(event, fn) {
    const listeners = this.#events.get(event);
    if (!listeners) return;
    listeners.delete(fn);
    if (listeners.size === 0) this.#events.delete(event);
  }

  emit(event, value) {
    const listeners = this.#events.get(event);
    if (!listeners) return;
    for (const fn of [...listeners.keys()]) fn(value);
  }
}

