class Emitter {
  // event -> Map<listener, unsubscribe>; Map insertion order is registration order
  #events = new Map();

  on(event, fn) {
    const subs = this.#subscribersOf(event);
    const existing = subs.get(fn);
    if (existing) return existing;

    const unsubscribe = () => {
      if (subs.get(fn) === unsubscribe) subs.delete(fn);
    };
    subs.set(fn, unsubscribe);
    return unsubscribe;
  }

  off(event, fn) {
    this.#events.get(event)?.delete(fn);
  }

  emit(event, value) {
    const subs = this.#events.get(event);
    if (!subs) return;
    // 快照：本次 emit 期间的增删只影响之后的 emit
    for (const fn of [...subs.keys()]) fn(value);
  }

  #subscribersOf(event) {
    let subs = this.#events.get(event);
    if (!subs) {
      subs = new Map();
      this.#events.set(event, subs);
    }
    return subs;
  }
}

