  const label = mapResult(ok(3), (n) => `#${n}`);
  assert.deepEqual(label, { ok: true, value: "#3" });
});

test("mapResult does not call fn on failure and returns the failure unchanged", () => {
  const failure: Result<number> = fail("boom");
  let calls = 0;
  const mapped = mapResult(failure, (n: number) => {
    calls++;
    return n * 2;
  });
  assert.equal(calls, 0);
  assert.equal(mapped, failure);
  assert.deepEqual(mapped, { ok: false, error: "boom" });
});

test("mapResult propagates exceptions thrown by fn", () => {
  assert.throws(
    () =>
      mapResult(ok(1), () => {
        throw new RangeError("bad input");
      }),
    RangeError,
  );
});

test("mapResult chains through several steps", () => {
  const parse = (s: string): Result<number> => {
    const n = Number(s);
    return Number.isNaN(n) ? fail(`not a number: ${s}`) : ok(n);
  };
  const result = mapResult(mapResult(parse("5"), (n) => n + 1), (n) => n * 10);
  assert.deepEqual(result, { ok: true, value: 60 });

  const bad = mapResult(mapResult(parse("x"), (n) => n + 1), (n) => n * 10);
  assert.deepEqual(bad, { ok: false, error: "not a number: x" });
});

