  assert.equal(unwrapOr(ok("hi"), "fallback"), "hi");
});

test("unwrapOr returns the fallback on failure", () => {
  assert.equal(unwrapOr(fail<string>("nope"), "fallback"), "fallback");
});

test("unwrapOr keeps falsy success values", () => {
  assert.equal(unwrapOr(ok(0), 99), 0);
  assert.equal(unwrapOr(ok(false), true), false);
});

