  assert.deepEqual(mapResult(ok(3), (n) => n + 1), { ok: true, value: 4 });
});

test("mapResult can change the value type", () => {
  assert.deepEqual(mapResult(ok(3), (n) => String(n)), { ok: true, value: "3" });
});

