        target = (base / relative).resolve()
    except RuntimeError as exc:
        raise ValueError("symlink loop in upload path") from exc
    if target == base:
        raise ValueError("upload target must not be the root directory")
    if not target.is_relative_to(base):
        raise ValueError("upload target escapes root")
    return target

